import java.util.Scanner;

public class Main {
    static long inf = 17446744073709551616L;
    static long[] factorial;
    static long[] invFactorial;
    static long[][] dpTable;
    static long modulus;
    static long n, k;

    static long fastPow(long base, long exponent) {
        long result = 1L;
        while (exponent > 0) {
            if ((exponent & 1L) == 1L) {
                result = (result * base) % modulus;
            }
            base = (base * base) % modulus;
            exponent >>= 1;
        }
        return result;
    }

    static long combination(int a, int b) {
        return (((factorial[a] * invFactorial[b]) % modulus) * invFactorial[a - b]) % modulus;
    }

    static long solve() {
        int i, j, l;
        factorial[0] = 1L;
        for (i = 1; i <= n; i++) {
            factorial[i] = (factorial[i - 1] * i) % modulus;
        }
        invFactorial[n] = fastPow(factorial[n], modulus - 2);
        for (i = n - 1; i >= 0; i--) {
            invFactorial[i] = (invFactorial[i + 1] * (i + 1)) % modulus;
        }
        for (i = 1; i <= n; i++) {
            dpTable[1][i] = invFactorial[i];
        }
        long result = (dpTable[1][(int) n] * combination((int) k, 1)) % modulus;
        int limit = (int) Math.min(17, k);
        for (i = 2; i <= limit; i++) {
            for (j = (int) n; j > 0; j = (j - 1) & (int) n) {
                for (l = j; l > 0; l = (l - 1) & j) {
                    dpTable[i][j] += dpTable[i - 1][j ^ l] * invFactorial[l];
                    if (dpTable[i][j] > inf) {
                        dpTable[i][j] %= modulus;
                    }
                }
                dpTable[i][j] %= modulus;
            }
            result += dpTable[i][(int) n] * combination((int) k, i);
            result %= modulus;
        }
        result = (result * factorial[(int) n]) % modulus;
        return result;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        n = sc.nextLong();
        k = sc.nextLong();
        modulus = sc.nextLong();

        dpTable = new long[18][250005];
        factorial = new long[250005];
        invFactorial = new long[250005];

        long answer = fastPow(k, n);
        if ((n & 1) == 1) {
            System.out.println(answer);
        } else {
            answer = (answer - solve() + modulus) % modulus;
            System.out.println(answer);
        }
        sc.close();
    }
}
